begin;
select no_plan();
insert into auth.users(id,email) values('e1000000-0000-4000-a000-000000000001','r4-a@example.test'),('e1000000-0000-4000-a000-000000000002','r4-b@example.test');
insert into public.food_concepts(id,slug,display_name) values('e2000000-0000-4000-a000-000000000001','r4-eggs','Huevos R4');
insert into public.recipe_import_jobs(id,user_id,idempotency_key,source_type,manual_text,state,result) values('e3000000-0000-4000-a000-000000000001','e1000000-0000-4000-a000-000000000001','r4-import-fixture','manual','Receta local','completed','{"schemaVersion":"recipe-v1","title":"Huevos R4","ingredients":[{"name":"Huevos R4","amount":"4","unit":"unit"}],"steps":["Cocinar"],"source":{"type":"manual"},"provenance":{"quality":{"status":"review_required"}}}');
insert into public.inventory_items(id,user_id,name,expiry_date,quantity,unit,added_at,food_concept_id,normalization_status,normalization_source,knowledge_provenance,stock_mode,quantity_precision,quantity_exact,quantity_unit) values('e4000000-0000-4000-a000-000000000001','e1000000-0000-4000-a000-000000000001','Huevos R4','2026-10-30',16,'unit',now(),'e2000000-0000-4000-a000-000000000001','confirmed','user','user','exact','exact',16,'unit');
create temp table tokens(plan uuid,event uuid,result jsonb);
grant all on tokens to authenticated;
create function pg_temp.r4_plan(mode text default 'exact') returns uuid language plpgsql as $$
declare recipe jsonb; version bigint; state text; r jsonb; plan uuid;
begin
 recipe:=public.cooking_v3_source('e1000000-0000-4000-a000-000000000001','import','e3000000-0000-4000-a000-000000000001');
 select i.version,i.stock_state into version,state from public.inventory_items i where id='e4000000-0000-4000-a000-000000000001';
 r:=jsonb_build_object('contract','cooking-plan-v1','recipeVersion',recipe->>'recipeVersion','recipe',recipe,'sourceRef',jsonb_build_object('kind','import','id','e3000000-0000-4000-a000-000000000001'),
 'lines',jsonb_build_array(jsonb_build_object('lineId','eggs','conceptId','e2000000-0000-4000-a000-000000000001','mode',mode,'required',4,'requiredUnit','unit','allowedActions',to_jsonb(array['keep','apply','set_state','set_consumption']),
 'allocations',jsonb_build_array(jsonb_build_object('inventoryItemId','e4000000-0000-4000-a000-000000000001','version',version)))));
 r:=public.store_cooking_v3_plan('e1000000-0000-4000-a000-000000000001','import','e3000000-0000-4000-a000-000000000001',public.cooking_v3_state('e1000000-0000-4000-a000-000000000001','import','e3000000-0000-4000-a000-000000000001'),r);
 return (r->>'planKey')::uuid;
end $$;
insert into tokens(plan) values(pg_temp.r4_plan());
select ok(not has_function_privilege('authenticated','public.store_cooking_v3_plan(uuid,text,uuid,text,jsonb)','EXECUTE'),'browser cannot publish authoritative plans');
select ok(not has_function_privilege('authenticated','public.cooking_v3_source(uuid,text,uuid)','EXECUTE'),'arbitrary-owner helper private');
select ok(not has_table_privilege('authenticated','public.cooking_v3_events','UPDATE'),'events append-only to browser');
select ok(not has_table_privilege('authenticated','public.cooking_v3_plans','INSERT'),'plan insertion private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-a000-000000000001","role":"authenticated"}',true);
select is(public.read_cooking_v3_context('import','e3000000-0000-4000-a000-000000000001')#>>'{recipe,title}','Huevos R4','own source readable');
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000001',false,'[{"lineId":"eggs","action":"apply"}]')->>'error','INVALID_REQUEST','provisional source requires acknowledgement');
update tokens set result=public.confirm_cooking_v3(plan,'e5000000-0000-4000-a000-000000000001',true,'[{"lineId":"eggs","action":"apply"}]');
update tokens set event=(result->>'eventId')::uuid;
select is((select result->>'status' from tokens),'applied','consumption applied');
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),12::numeric,'16 eggs minus 4 equals12');
select is((select quantity from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),12::numeric,'proven exact consumption mirrored for legacy reads');
select is((select result#>>'{changes,0,provenance}' from tokens),'recipe_consumption','consumption provenance');
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000001',true,'[{"lineId":"eggs","action":"apply"}]')->>'status','duplicate','replay precedes pantry conflict');
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000001',true,'[{"lineId":"eggs","action":"keep"}]')->>'error','MUTATION_CONFLICT','payload cannot change under same ID');
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000002',true,'[{"lineId":"eggs","action":"apply"}]')->>'error','PANTRY_CONFLICT','second gesture cannot reuse changed stock');
select is(public.undo_cooking_v3((select event from tokens),'e5000000-0000-4000-a000-000000000003')->>'status','applied','immediate undo applies');
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),16::numeric,'undo restores original quantity');
select is(public.undo_cooking_v3((select event from tokens),'e5000000-0000-4000-a000-000000000004')->>'status','duplicate','distinct undo gesture returns compensation');
select is((select count(*) from public.cooking_v3_events where user_id=auth.uid()),2::bigint,'one consumption and one append-only compensation');
select is(public.undo_cooking_v3((select event from tokens),'e5000000-0000-4000-a000-000000000001')->>'error','MUTATION_CONFLICT','cross-operation mutation ID rejected');
reset role;
update tokens set plan=pg_temp.r4_plan();
set local role authenticated;
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000005',true,'[{"lineId":"eggs","action":"set_consumption","quantity":18,"unit":"unit"}]')->>'error','INVALID_REQUEST','overconsumption rejected');
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),16::numeric,'invalid adjustment writes nothing');
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000005',true,'[{"lineId":"eggs","action":"apply"},{"lineId":"eggs","action":"apply"}]')->>'error','INVALID_REQUEST','duplicate choice rejected');
update tokens set result=public.confirm_cooking_v3(plan,'e5000000-0000-4000-a000-000000000005',true,'[{"lineId":"eggs","action":"set_consumption","quantity":2,"unit":"unit"}]');
update tokens set event=(result->>'eventId')::uuid;
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),14::numeric,'explicit consumed amount applied');
select is((select result#>>'{changes,0,provenance}' from tokens),'user_adjustment','explicit input not extraction evidence');
reset role;
update public.inventory_items set notes='another device',version=version+1 where id='e4000000-0000-4000-a000-000000000001';
set local role authenticated;
select is(public.undo_cooking_v3((select event from tokens),'e5000000-0000-4000-a000-000000000006')->>'error','UNDO_CONFLICT','later same-value edit blocks undo by version');
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),14::numeric,'undo conflict restores nothing');
reset role;
update public.cooking_v3_events set undo_until=statement_timestamp()-interval '1 second' where id=(select event from tokens);
set local role authenticated;
select is(public.undo_cooking_v3((select event from tokens),'e5000000-0000-4000-a000-000000000007')->>'error','UNDO_EXPIRED','five-minute server window enforced');
reset role;
update tokens set plan=pg_temp.r4_plan();
update public.cooking_v3_plans set expires_at=statement_timestamp()-interval '1 second' where id=(select plan from tokens);
set local role authenticated;
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000008',true,'[{"lineId":"eggs","action":"apply"}]')->>'error','PLAN_EXPIRED','expired plan blocks new confirmation');
reset role;
update tokens set plan=pg_temp.r4_plan('unresolved');
set local role authenticated;
update tokens set result=public.confirm_cooking_v3(plan,'e5000000-0000-4000-a000-000000000009',true,'[{"lineId":"eggs","action":"set_state","inventoryItemId":"e4000000-0000-4000-a000-000000000001","state":"low"}]');
select is((select stock_state from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),'low','qualitative choice applies without arithmetic');
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),null::numeric,'exact quantity cleared on qualitative choice');
select is((select quantity_precision from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),'unknown','precision not invented');
select is((select notes from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),'another device','unrelated metadata preserved');
reset role;
update tokens set plan=pg_temp.r4_plan('qualitative');
set local role authenticated;
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000010',true,'[{"lineId":"eggs","action":"apply"}]')->>'status','applied','qualitative proposal confirmable');
select is((select stock_state from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),'empty','low transitions to empty');
select is((select deleted_at from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),null::timestamptz,'empty item not deleted');
reset role;
update tokens set plan=pg_temp.r4_plan('unresolved');
set local role authenticated;
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000011',true,'[{"lineId":"eggs","action":"keep"}]')->>'status','applied','all keep still records cooking event');
select is((select quantity_exact from public.inventory_items where id='e4000000-0000-4000-a000-000000000001'),null::numeric,'keep does not invent quantity');
select is((select count(*) from public.recipe_import_usage where user_id=auth.uid()),0::bigint,'cooking does not use import quota');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-a000-000000000002","role":"authenticated"}',true);
select is(public.read_cooking_v3_context('import','e3000000-0000-4000-a000-000000000001')->>'error','SOURCE_NOT_FOUND','foreign source uniform404');
select is(public.confirm_cooking_v3((select plan from tokens),'e5000000-0000-4000-a000-000000000012',true,'[{"lineId":"eggs","action":"keep"}]')->>'error','SOURCE_NOT_FOUND','foreign plan uniform404');
select is(public.undo_cooking_v3((select event from tokens),'e5000000-0000-4000-a000-000000000013')->>'error','SOURCE_NOT_FOUND','foreign event uniform404');
select is((select count(*) from public.cooking_v3_events),0::bigint,'event RLS isolates accounts');
select is((select count(*) from public.cooking_v3_plans),0::bigint,'plan RLS isolates accounts');
select * from finish();
rollback;
